import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { FaUser, FaEnvelope, FaLock } from 'react-icons/fa';
import './Auth.css';

const Register = () => {
  const [showPassword, setShowPassword] = useState(false);

  return (
    <div className="auth-bg">
      <div className="auth-container">
        <div className="auth-logo">GI</div>
        <h2>Register</h2>
        <div className="auth-tagline">Create your account to get started with Global Image.</div>
        <form className="auth-form">
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaUser /></span>
            <input type="text" id="name" name="name" placeholder="Name" required />
          </div>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaEnvelope /></span>
            <input type="email" id="email" name="email" placeholder="Email" required />
          </div>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaLock /></span>
            <input type={showPassword ? 'text' : 'password'} id="password" name="password" placeholder="Password" required />
            <button type="button" className="toggle-password" onClick={() => setShowPassword(s => !s)}>{showPassword ? '🙈' : '👁️'}</button>
          </div>
          <button type="submit">Register</button>
        </form>
        <div className="auth-links">
          <Link to="/signin">Already have an account?</Link>
        </div>
      </div>
    </div>
  );
};

export default Register;
